export interface Layout { width:number; height:number; portrait:boolean; contentX:number; contentWidth:number; }
export function layoutFor(width:number,height:number):Layout{
 const aspect=Math.max(1,width)/Math.max(1,height),portrait=aspect<.9;
 // A separate composition per orientation, without stretching or cropping.
 const logicalWidth=portrait?720:Math.max(1280,800*aspect);
 const logicalHeight=portrait?720/aspect:Math.max(800,1280/aspect);
 return {width:logicalWidth,height:logicalHeight,portrait,contentX:portrait?0:(logicalWidth-1280)/2,contentWidth:portrait?720:1280};
}

/** Portrait game group fits the viewport as one unit; no oversized fixed header gap. */
export function portraitBoard(width:number,height:number,columns:number,rows:number,top:number,gap=4){
 const reserve=height<1100?352:462,inset=gap===0?16:20;
 const cell=Math.max(28,Math.floor(Math.min((width-64-inset-gap*(columns-1))/columns,(height-top-reserve-inset-gap*(rows-1))/rows)));
 const boardWidth=cell*columns+gap*(columns-1)+inset,boardHeight=cell*rows+gap*(rows-1)+inset;
 const y=top+Math.max(0,(height-top-reserve-boardHeight)/2);
 return{cell,boardWidth,boardHeight,x:(width-boardWidth)/2,y};
}
