export interface LinePoint {x:number;y:number;}
/** Extend a payline through the outer symbol edges, clipped to the reel interior. */
export function paylinePath(cells:number[],columns:number,rows:number,cell:number,gap:number,inset:number):LinePoint[]{
 if(!cells.length)return [];
 const step=cell+gap,points=cells.map(i=>({x:inset+(i%columns)*step+cell/2,y:inset+Math.floor(i/columns)*step+cell/2}));
 const left=inset,right=inset+(columns-1)*step+cell,top=inset,bottom=inset+(rows-1)*step+cell;
 const extend=(p:LinePoint,q:LinePoint,bound:number)=>{
  const dx=p.x-q.x,dy=p.y-q.y;if(dx===0)return {x:bound,y:p.y};
  let t=(bound-p.x)/dx;const y=p.y+t*dy;
  if(y<top&&dy!==0)t=(top-p.y)/dy;else if(y>bottom&&dy!==0)t=(bottom-p.y)/dy;
  return {x:p.x+t*dx,y:p.y+t*dy};
 };
 return [extend(points[0],points[1]||{x:points[0].x+1,y:points[0].y},left),...points,extend(points[points.length-1],points[points.length-2]||{x:points[0].x-1,y:points[0].y},right)];
}
